    // moves until the person is ready. Autonomous steps never advance on a timer.
    "walk.ready": "That's done. Take your time — tap Next when you're ready.",
    "walk.readyLast": "All done. This will close in a moment — or tap Done.",
    // Honest refusals. A walkthrough Mei has just promised but the app cannot
    // run must SAY so — silence here is indistinguishable from being broken.
    "walk.refused.wrongShell": "Sorry — that walkthrough belongs to the other view of the app, so I can't show it to you here. Ask me and I'll explain it instead.",
    "walk.refused.nothingLow": "Good news — none of your medications are running low right now, so there's nothing to request a refill for yet. I'll tell you when one is.",
    "walk.refused.nothingToShow": "Good news — there's nothing waiting for you on the Reminders page right now, so there'd be nothing to show you. I'll walk you through it the moment something needs you.",
    "walk.refused.noCaregiver": "You don't have a caregiver linked yet, so there's no emergency contact to show you. Shall I help you add one?",
    "walk.refused.noPendingRequest": "You don't have a caregiver request waiting right now, so there's nothing to accept. I'll bring you straight there when one arrives.",
    // Honest stuck-states. These used to be a silent black screen with no way
    // out; now the card always renders, so there is always an Exit.
    "walk.cannotFind": "Sorry — I can't find that on this screen, so I've stopped rather than guess. Tap Exit and I'll help another way.",
    "walk.timedOut": "I didn't see that happen, so I've stopped here. You can try again, or tap Exit and ask me instead.",
    // Guided Auto-Navigation — Mei acts, then re-checks real state before moving on.
    "walk.verifyFailed": "Hmm — I couldn't confirm that saved. I've stopped here so nothing's assumed. Let's try again or I'll get a person to help.",
    "walk.taskLabel.addPrescriptionAuto": "adding a prescription for you",
    "walk.autoRx.open": "I'll open the Add Prescription form for you — watch here.",
    "walk.autoRx.name": "Filling in the medication name…",
    "walk.autoRx.dose": "Adding the dose…",
    "walk.autoRx.purpose": "And what it's for…",
    "walk.autoRx.durationMode": "This one is only for a set number of days, so I'll switch it to a fixed course.",
    "walk.autoRx.duration": "Now I'll set how long you take it for.",
    // Shared final "you tap Save" step across every auto walkthrough — nothing is
    // saved on autopilot; the person confirms with their own tap.
    "walk.confirmSave": "I've filled it in. Please check it below — if anything's wrong tap Change something; when it looks right, tap Next.",
    "walk.confirmCheck": "Please check what I've entered on the form — when it looks right, tap Next.",
    // The step AFTER the recap above — the real Save tap. No review card here
    // any more (it moved onto the recap step), just the plain instruction.
    "walk.confirmSubmit": "Everything's ready — go ahead and tap Save yourself to finish.",
    // The review card (components/WalkthroughReview.tsx): the person can see
    // exactly what Mei typed before they commit it.
    "walk.review.title": "Please check these details",
    "walk.review.change": "Change something",
    "walk.review.empty": "— not filled in —",
    // Row label for the doctor-question confirm step's review card.
    "walk.review.question": "Question",
    // Confirm phase clarifying question (decision B): a blank field always
    // blocks Submit, regardless of trust/risk — this is the inline prompt +
    // its one new button (the other option reuses "Change something" above).
    "walk.confirm.blankPrompt": "It looks like {label} is still empty. Tap \"Change something\" above to add it, or \"Continue without\" to save it as is.",
    "walk.confirm.continueWithout": "Continue without",
    // The action-row indicator on user-driven (consent) steps — same slot as
    // Next, but never pressable: it names the REAL control to tap, so every
    // step's callout has the same shape. Derived from the target's own
    // accessible name, so it can't drift from the UI.

