    "common.you": "您",
    "welcome.title": "您的智能用药管家",
    "welcome.subtitle": "帮您记住每一次服药，温和提醒，并与关心您的人保持联系。",
    "summary.insight1Title": "中午的 Celecoxib 经常漏服",
    "summary.insight1Body": "本周七天里，有三天漏服了中午 12:00 的 Celecoxib。这是最常漏服的药物，可能与午餐时间的作息被打乱有关。",
    "summary.insight2Title": "早上的服药习惯已经很稳定",
    "summary.insight2Body": "早上 7:00 的 Metformin 和 Amlodipine 每天都按时服用，平均与预定时间相差不到 12 分钟。这两次服药的依从性非常好。",
    "summary.insight3Title": "比上周略有下降",
    "summary.insight3Body": "依从率由上周的 89% 降至 82%。作息没有明显改变；可能与{nickname}本周提到关节更不舒服有关。",
    "summary.point1": "可考虑把 Celecoxib 200mg 移到一个已有的日常习惯之后（例如午饭后看电视的时候），以改善中午的服药情况。",
    "summary.point2": "谈一谈{nickname}提到的关节疼痛，以及漏服 Celecoxib 是否让不适加重——这是一个值得留意的恶性循环。",
    "summary.point3": "Metformin 需在四天内补药。请在下次到综合诊疗所时开药，或通过 OneDoc／Health Buddy 应用申请。",
    "summary.doctorFallback": "您的医生",
    "messages.myRole": "儿子",
    "messages.thread1.role": "女佣",
    "messages.thread1.body": "早安！陈女士早餐时已经吃了早上的药。今天看起来有点累，不过吃得不错。",
    "messages.thread2.role": "儿子",
    "messages.thread2.body": "谢谢 Siti。也请提醒她午饭后做脚部运动。",
    "messages.thread3.role": "姐妹",
    "messages.thread3.body": "我星期六会过去，到时候一起看看 Celecoxib 的情况好吗？她老是忘记中午那一次。",
    "messages.thread4.role": "儿子",
    "messages.thread4.body": "好主意。我会留个字条给 Siti。也许可以在 11:30 把药放在餐桌上，让她一看就想起来。",
    "messages.thread5.role": "女佣",
    "messages.thread5.body": "知道了！我会连同一小杯水一起放好。她今天午饭时又忘了——说是在看电视。",
