    "welcome.title": "你的智慧食藥助手",
    "welcome.subtitle": "共你的藥記予好，溫柔提醒，閣佮關心你的人保持聯絡。",
    "summary.insight1Title": "中晝的 Celecoxib 定定袂記得食",
    "summary.insight1Body": "這禮拜七工內底，有三工無食著中晝 12:00 的 Celecoxib。這是上定定漏食的藥，可能佮中晝的作息予人拍亂有關係。",
    "summary.insight2Title": "早起的食藥習慣已經真穩",
    "summary.insight2Body": "早起 7:00 的 Metformin 佮 Amlodipine 逐工攏有準時食，平均佮排定的時間差袂到 12 分鐘。這兩擺的藥食了真好。",
    "summary.insight3Title": "比頂禮拜小可仔落",
    "summary.insight3Body": "食藥的準時率對頂禮拜的 89% 落到 82%。作息無啥物變；可能佮{nickname}這禮拜講關節較袂爽快有關係。",
    "summary.point1": "會使考慮共 Celecoxib 200mg 徙到本底就有的習慣了後（親像中晝飯後看電視的時），按呢中晝較袂漏食。",
    "summary.point2": "共醫生講{nickname}講的關節疼，閣看漏食 Celecoxib 敢有予艱苦加重——這款循環愛盯予好。",
    "summary.point3": "Metformin 愛佇四工內補藥。下擺去綜合診療所的時開藥，抑是用 OneDoc／Health Buddy 應用申請。",
    "summary.doctorFallback": "你的醫生",
    "messages.myRole": "後生",
    "messages.thread1.role": "幫傭",
    "messages.thread1.body": "賢早！陳女士食早頓的時已經共早起的藥食矣。今仔日看起來小可仔忝，毋過食了袂䆀。",
    "messages.thread2.role": "後生",
    "messages.thread2.body": "多謝 Siti。嘛麻煩提醒伊中晝飯後做跤的運動。",
    "messages.thread3.role": "姊妹",
    "messages.thread3.body": "我拜六會去，到時做伙看 Celecoxib 的情形好無？伊定定袂記得中晝彼擺。",
    "messages.thread4.role": "後生",
    "messages.thread4.body": "好主意。我會留字條予 Siti。凡勢會使 11:30 共藥囥佇食飯桌頂，予伊一下看著就會記得。",
    "messages.thread5.role": "幫傭",
    "messages.thread5.body": "知影矣！我會連細杯水做伙园好。伊今仔日中晝閣袂記得矣——講伊咧看電視。",
