    "eyedrop.step2": "தலையைப் பின்னால் சாய்த்து மேற்கூரையைப் பாருங்கள்",
    "eyedrop.step3": "கீழ் இமையை மெதுவாகக் கீழிழுத்து ஒரு சிறிய பை உருவாக்குங்கள்",
    "eyedrop.step4": "பாட்டிலைக் கண்ணுக்கு மேலே பிடித்து, அந்தப் பையில் 1 சொட்டு விடுங்கள்",
    "eyedrop.step5": "கண்ணை மெதுவாக மூடுங்கள் — சிமிட்டவோ தேய்க்கவோ வேண்டாம்",
    "eyedrop.step6": "உள்வாங்க உதவ கண்ணின் உட்புற மூலையை 1 நிமிடம் அழுத்தி வையுங்கள்",
    "eyedrop.step7": "மற்றொரு கண்ணுக்கும் இதையே செய்யுங்கள். ஒவ்வொரு இரவும் படுக்கைக்கு முன் பயன்படுத்துங்கள்",
    "prescription.eyeDropsAlt": "கண் சொட்டு மருந்து செயல்விளக்கம்",
    "prescription.watchHowToUse": "பார்க்க: கண் சொட்டு மருந்தை எப்படி பயன்படுத்துவது",
