    "ai.reportMsg": "📄 இது ஒரு மருத்துவமனை அறிக்கை. இதிலிருந்து மருத்துவ சுயவிவரத்தைப் புதுப்பிக்கவும்.",
    "ai.reportMsgMine": "📄 இது எனது மருத்துவமனை அறிக்கை. இதிலிருந்து எனது மருத்துவ சுயவிவரத்தைப் புதுப்பிக்கவும்.",
    "ai.elderGreeting": "{nick}, சுப {timeOfDay}! 😊\n\nநான் Mei, உங்கள் மருந்து உதவியாளர். {nextInfo}\n\nவிரைவு உதவிக்கு மேலே உள்ள பொத்தானைத் தட்டவும், அல்லது கீழே உங்கள் கேள்வியை தட்டச்சு செய்யவும்.",
    "ai.elderGreetingNext": "உங்கள் அடுத்த மருந்து {name} ({dose}), {time} மணிக்கு.",
    "ai.elderGreetingAllDone": "இன்று உங்கள் மருந்துகள் அனைத்தையும் எடுத்துவிட்டீர்கள் — அருமை! 🌟",
    "ai.setupIntro": "{nick}, உங்களை அமைக்க உதவுகிறேன்! நான் செய்யக்கூடியவை:\n\n📷 ஒரு மருந்தைச் சேர்க்கவும் — “மருந்துச்சீட்டு சேர்க்கவும்” தட்டி பெட்டியின் புகைப்படம் எடுக்கவும்.\n📄 உங்கள் சுகாதார சுயவிவரத்தைப் புதுப்பிக்கவும் — ஒரு அறிக்கையை பதிவேற்றவும், நான் படிக்கிறேன்.\n💊 ஒரு மருந்தைப் பற்றி கேளுங்கள் — “ஒரு மருந்தைப் பற்றி கேளுங்கள்” தட்டி ஒன்றைத் தேர்ந்தெடுக்கவும்.\n🌐 மொழியை மாற்றவும் அல்லது எனது குரலை ஆன்/ஆஃப் செய்யவும்.\n\nமுதலில் என்ன செய்ய விரும்புகிறீர்கள்?",
    "ai.notSureAskDoctor": "Mei-க்கு உறுதியாகத் தெரியவில்லை — உங்கள் மருத்துவரிடம் கேளுங்கள்",
