    "common.forLovedOneDesc": "அட்டவணைகள், மருந்துச்சீட்டுகளை நிர்வகித்து முன்னேற்றத்தைக் கண்காணிக்கவும்",
    "common.forMyselfDesc": "எனது தினசரி மருந்துகளை நிர்வகித்து உதவி கேட்கவும்",
    "tour.cgDashboardTitle": "இன்றைய பின்பற்றல்",
    "tour.cgDashboardBody": "இன்று எத்தனை அளவுகள் எடுக்கப்பட்டன என்பதை ஒரே பார்வையில் காணவும், முழு அட்டவணைக்கும் செல்லவும்.",
    "tour.cgMedsTitle": "தற்போதைய மருந்துகள்",
    "tour.cgMedsBody": "நீங்கள் நிர்வகிக்கும் ஒவ்வொரு மருந்தும், மறுநிரப்பு நிலையுடன் — எப்போது வேண்டுமானாலும் புதிதாகச் சேர்க்கலாம்.",
    "tour.cgAskMeiTitle": "Mei-ஐக் கேளுங்கள்",
    "tour.cgAskMeiBody": "பின்பற்றல், தவறவிட்ட மருந்துகள் அல்லது மறுநிரப்புகளைப் பற்றி கேளுங்கள், வாராந்திர சுருக்கத்தைப் பெறுங்கள், அல்லது பயண பயன்முறையில் ஒரு பயணத்தைத் திட்டமிடுங்கள்.",
    "tour.cgNotifTitle": "அறிவிப்புகள்",
    "tour.cgNotifBody": "நீங்கள் எச்சரிக்கப்பட வேண்டியதைத் தேர்ந்தெடுக்கவும் — தவறவிட்ட மருந்துகள், குறைந்த இருப்பு, வாராந்திர சுருக்கங்கள்.",
    "tour.cgPatientLinkTitle": "நோயாளியைச் சேர்க்கவும் அல்லது மாற்றவும்",
    "tour.cgPatientLinkBody": "நோயாளியை மாற்றுவது, கைமுறையாகச் சேர்ப்பது, அல்லது அவர்களின் அமைப்புகளில் உள்ள QR குறியீட்டை ஸ்கேன் செய்து இணைப்பது — எல்லாம் இங்கேதான்.",
    "tour.elderScheduleTitle": "உங்கள் தினசரி அட்டவணை",
    "tour.elderScheduleBody": "உங்கள் நாளின் மருந்துகள் இங்கே, நீங்கள் எடுக்கும் நேரத்தில் தோன்றும். நேரம் வந்ததும், அட்டையை ஒருமுறை தட்டினால் எடுத்ததாகக் குறிக்கப்படும்.",
    "tour.elderMedsTitle": "உங்கள் மருந்துகள்",
    "tour.elderMedsBody": "நீங்கள் எடுக்கும் ஒவ்வொரு மருந்தையும், எப்படி எடுப்பது, எவ்வளவு இருப்பு உள்ளது என்பதையும் பார்க்கவும்.",
    "tour.elderAddRxTitle": "புதிய மருந்துச்சீட்டைச் சேர்க்கவும்",
    "tour.elderAddRxBody": "இந்தப் பொத்தான் புதிய மருந்தைச் சேர்க்க — தட்டச்சு செய்யலாம், அல்லது லேபிளின் புகைப்படம் எடுக்கலாம்.",
    "tour.elderAskMeiTitle": "Mei-ஐக் கேளுங்கள்",
    "tour.elderAskMeiBody": "எப்போது வேண்டுமானாலும் Mei உடன் அரட்டையடிக்கவும் — புகைப்படம் மூலம் மருந்துச்சீட்டு சேர்க்கவும், மருந்தைப் பற்றி கேளுங்கள், அல்லது பயண பயன்முறையில் பயணத்தைத் திட்டமிடுங்கள்.",
    "tour.elderProfileTitle": "உங்கள் சுயவிவரம்",
    "tour.elderProfileBody": "உங்கள் வயது, நிலைமைகள், ஒவ்வாமைகள் மற்றும் பலவற்றை எப்போது வேண்டுமானாலும் இங்கே புதுப்பிக்கவும் — இதைத்தான் Mei உங்களைப் பாதுகாக்கப் பயன்படுத்துகிறது.",
    "tour.elderFontTitle": "எழுத்தை படிக்க எளிதாக்கவும்",
    "tour.elderFontBody": "எழுத்தை பெரிதாகவோ சிறியதாகவோ மாற்ற இதை இழுக்கவும், உங்களுக்கு வசதியானதைத் தேர்ந்தெடுக்கவும்.",
    "tour.elderLangTitle": "மொழி மற்றும் குரல்",
    "tour.elderLangBody": "Mei பேசும் மற்றும் தட்டச்சு செய்யும் மொழியை மாற்றவும், அவளுடைய குரல் பதில்களை ஆன்/ஆஃப் செய்யவும்.",
    "tour.elderQrTitle": "உங்கள் பராமரிப்பாளரை இணைக்கவும்",
    "tour.elderQrBody": "உங்கள் பராமரிப்பாளர் தங்கள் ஆப்பிலிருந்து இந்தக் குறியீட்டை ஸ்கேன் செய்து, உங்கள் மருந்துகளை அணுக அனுமதி கோரலாம்.",
    "confirm.replayTourTitle": "வழிகாட்டியை மீண்டும் இயக்கவா?",
    "confirm.replayTourBody": "டாஷ்போர்டிலிருந்து தொடங்கி, முக்கிய அம்சங்களை மீண்டும் உங்களுக்குக் காண்பிப்போம்.",
    "confirm.replay": "மீண்டும் இயக்கு",
    "toast.missedDoseTitle": "தவறவிட்ட மருந்து — {med}",
    "toast.missedDoseBody": "{name} தனது {time} {med} {dose} அளவை எடுக்கவில்லை.",
    "toast.refillNeededTitle": "மறுநிரப்பு விரைவில் தேவை — {med}",
    "toast.refillNeededBody": "{med} இல் சுமார் {days} நாட்கள் மீதம் உள்ளது.",
