    "toast.reminderFromCaregiver": "உங்கள் பராமரிப்பாளரிடமிருந்து நினைவூட்டல்",
    "confirm.replayTourBodyElder": "முகப்பிலிருந்து தொடங்கி, முக்கிய அம்சங்களை மீண்டும் உங்களுக்குக் காண்பிப்போம்.",
