export function t(language: AppLanguage, key: string, params?: Record<string, string | number>) {
  const value = TRANSLATIONS[language]?.[key] ?? TRANSLATIONS.en[key] ?? key;
  return Object.entries(params ?? {}).reduce((acc, [k, v]) => acc.replaceAll(`{${k}}`, String(v)), value);
}

export function getLanguageLabel(language: AppLanguage) {
  return LANGUAGE_OPTIONS.find(option => option.id === language)?.label ?? LANGUAGE_OPTIONS[0].label;
}

// The natural-language name sent to Hermes as `reply_language` ("reply in {x}").
//
// English is "English", NOT undefined. An undefined value is dropped by
// JSON.stringify, so the whole LANGUAGE block was omitted from the system prompt
// — meaning switching zh→en REMOVED the only language instruction instead of
// replacing it, while the entire replayed conversation history was still in
// Chinese. Mei duly kept answering in Chinese. Every language now sends an
// explicit, authoritative instruction.
const REPLY_LANGUAGE: Record<AppLanguage, string | undefined> = {
  en: "English",
  zh: "Mandarin Chinese",
  hokkien: "Hokkien",
  yue: "Cantonese",
  ta: "Tamil",
  ms: "Malay",
};

export function replyLanguageFor(language: AppLanguage): string | undefined {
  return REPLY_LANGUAGE[language];
}

// Browser SpeechRecognition / speechSynthesis language tags.
const SPEECH_LANG: Record<AppLanguage, string> = {
  en: "en-SG",
  zh: "zh-CN",
  hokkien: "zh-CN",
  yue: "zh-HK",
  ta: "ta-IN",
  ms: "ms-MY",
};

export function speechLangFor(language: AppLanguage): string {
  return SPEECH_LANG[language];
}

// Optional curated, human-reviewed translations of a medication's simple
// instruction, keyed by language → medication name. Medication dosing text is
// safety-sensitive, so we deliberately do NOT machine-translate it: when no
// curated string exists we fall back to the (curated, English) `fallback` the
// caller passes in rather than risk a wrong auto-translation of a dose. Extend
// this table with reviewed translations to localise med directions per language.
type MedTextStyle = "simple";
const MED_TEXT_I18N: Partial<Record<AppLanguage, Record<string, string>>> = {};

export function localizeMedText(
  language: AppLanguage,
  medName: string,
  _style: MedTextStyle,
  fallback: string,
): string {
  return MED_TEXT_I18N[language]?.[medName] ?? fallback;
}
